function routineForToday(){var rows=[['tv','Mira la televisión: suerte y clima'],['forage','Recoge forraje que aparezca en el camino']];if(game.hasCrops){rows.unshift(['water',game.weather==='rain'?'Hoy llueve; no necesitas regar':'Riega los cultivos que no cubren los aspersores']);rows.push(['harvest','Revisa si hay cosechas listas']);}if(game.hasAnimals)rows.push(['animals','Alimenta y atiende a tus animales']);if(game.hasPet)rows.push(['pet','Llena el cuenco y saluda a tu mascota']);if(game.hasMachines)rows.push(['machines','Recoge y vuelve a cargar tus máquinas']);rows.push(['fiber','Corta maleza solo si necesitas fibra; conserva hierba alta para heno.']);return rows}
function renderDaily(){
 var day=game.day,seasonName=game.season,dow=(day-1)%7,route=routeForToday(day,seasonName),done=route.filter(function(row){return !!extra.dailyChecks[gameDate(day,seasonName,game.year)+'|route|'+row[0]]}).length,icon={Primavera:'🌷',Verano:'☀️',Otoño:'🍂',Invierno:'❄️'}[seasonName];
 $('#dailySummary').innerHTML='<article class="game-day-card"><div class="game-day-head"><span class="day-number">'+day+'</span><div><small>AÑO '+game.year+' · '+seasonName.toLocaleUpperCase('es')+'</small><b>Hoy es '+weekdays[dow]+' · '+seasonName.toLowerCase()+' '+day+'</b><span>'+icon+' '+(game.weather==='rain'?'Día lluvioso':'Clima: revisa la televisión')+' · '+fmt(game.gold)+'g</span></div><div class="day-progress">'+done+'/'+route.length+'<small>pasos listos</small></div></div><div class="day-controls"><label>Clima<select id="weatherSelect"><option value="unknown" '+(game.weather==='unknown'?'selected':'')+'>Aún no lo sé</option><option value="sunny" '+(game.weather==='sunny'?'selected':'')+'>Soleado</option><option value="rain" '+(game.weather==='rain'?'selected':'')+'>Lluvia</option></select></label><label class="check-row"><input id="hasCrops" type="checkbox" '+(game.hasCrops?'checked':'')+'><span>Tengo cultivos</span></label><label class="check-row"><input id="hasAnimals" type="checkbox" '+(game.hasAnimals?'checked':'')+'><span>Tengo animales</span></label><label class="check-row"><input id="hasPet" type="checkbox" '+(game.hasPet?'checked':'')+'><span>Ya adopté mi mascota</span></label><label class="check-row"><input id="hasMachines" type="checkbox" '+(game.hasMachines?'checked':'')+'><span>Tengo máquinas</span></label></div><div class="today-route"><div class="route-title"><span>✿</span><div><b>Tu ruta para hoy</b><small>Al completar un paso desaparece de esta ruta. Mañana el checklist empieza limpio y recuperas '+fmt(game.maxEnergy)+' de energía.</small></div></div>'+route.filter(function(row){return !extra.dailyChecks[gameDate(day,seasonName,game.year)+'|route|'+row[0]]}).map(function(row){var k=gameDate(day,seasonName,game.year)+'|route|'+row[0],checked=!!extra.dailyChecks[k];return '<label class="route-task '+(checked?'checked':'')+'"><input type="checkbox" data-route="'+row[0]+'" '+(checked?'checked':'')+'><span>'+row[1]+'</span><div><b>'+row[2]+'</b><small>'+row[3]+'</small></div></label>'}).join('')+'</div><details class="daily-loot"><summary>🧺 Registrar hallazgos de hoy</summary><div class="daily-loot-row"><label>Objeto<input id="dailyItem" list="resourceOptions" placeholder="Ej. Madera"></label><label>Cantidad<input id="dailyQty" type="number" min="1" value="1"></label><label>Precio base c/u<input id="dailyPrice" type="number" min="0" value="0"></label><label>Decisión<select id="dailyDecision"><option value="guardar">Guardar</option><option value="vender">Vender</option><option value="enviar">Enviar</option><option value="comprar">Comprar · descontar oro</option></select></label><button id="dailyAddItem" class="button-soft">＋ Anotar</button></div><small id="dailyItemHint">Anota madera, carbón y otros hallazgos; el total guardado se acumula en tu mochila.</small></details><div class="day-close"><div><b>Saldo calculado: '+fmt(game.gold)+'g</b><small>Se actualiza con tus ventas y compras registradas. Los envíos se cobran al despertar.</small></div><button id="closeDayBtn" class="button-primary">Cerrar el día '+day+' y avanzar →</button><small>Registra compras de semillas y gastos como “Comprar”; el oro y el calendario se actualizan solos.</small></div></article>'+(seasonName==='Primavera'&&day<13?renderSavings():'')+'<div class="objective-header"><div><b>Metas que siguen abiertas</b><small>Cuando marcas una como lista, desaparece de esta vista.</small></div></div><div class="objective-grid">'+(objectiveRows().map(function(row){var key=goalKey(row[0]);return '<label class="objective-card"><input type="checkbox" data-objective="'+row[0]+'" '+(extra.objectives[key]?'checked':'')+'><span>'+row[1]+'</span><div><b>'+row[2]+'</b><small>'+row[3]+'</small></div></label>'}).join('')||'<div class="empty-state">¡Todas tus metas están listas! Disfruta el valle a tu ritmo ♡</div>')+'</div>';
 var routines=routineForToday(),dk=gameDate(day,seasonName,game.year);updateShopStatuses(day,seasonName);
 $('#routineList').innerHTML=routines.map(function(row){return '<label class="routine-row"><input type="checkbox" data-routine="'+row[0]+'" '+(extra.routineChecks[dk+'|'+row[0]]?'checked':'')+'><span>'+row[1]+'</span></label>'}).join('');
 var days=Array.from({length:Math.min(13,29-day)},function(_,i){return day+i});
 $('#dayList').innerHTML=days.map(function(d){var tasks=dailyTasks(d,seasonName),today=d===day;return '<article class="day-card '+(today?'today':'')+'"><div class="day-heading"><span class="day-number">'+d+'</span><div><b>'+seasonName+' '+d+' · '+weekdays[(d-1)%7]+'</b><small>'+(today?'TU DÍA ACTUAL':'ADELANTO DEL CALENDARIO')+'</small></div>'+(d===13&&seasonName==='Primavera'?'<span class="day-badge">🍓 Fresas</span>':'')+'</div><div class="day-tasks">'+tasks.map(function(t,i){var k=game.year+'|'+seasonName+'|'+d+'|'+i;return '<label class="day-task"><input type="checkbox" data-day-task="'+encodeURIComponent(k)+'" '+(extra.dailyChecks[k]?'checked':'')+'><span>'+t[0]+'<small>'+t[1]+'</small></span></label>'}).join('')+'</div></article>'}).join('')||'<div class="empty-state">Cierra el día para ver el calendario de la siguiente estación.</div>';
}
function updateShopStatuses(day,seasonName){var tomorrow=nextDate(day,seasonName,game.year);['pierre','robin','clint','marnie','willy','cart'].forEach(function(id){var now=$('[data-shop-status="'+id+'"]'),next=$('[data-shop-tomorrow="'+id+'"]');if(now)now.textContent=storeStatus(id,day,seasonName,game.weather,game.year);if(next)next.textContent='Mañana: '+storeStatus(id,tomorrow.day,tomorrow.season,'unknown',tomorrow.year)})}
function escapeHTML(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}
function resourceAdvice(name){var lower=name.toLocaleLowerCase('es'),pending=[];ccData.forEach(function(room){room.bundles.forEach(function(bundle){bundle.items.forEach(function(item){if(item[0].toLocaleLowerCase('es').includes(lower)&&!completed[key(room.room,bundle.n,item[0])])pending.push(bundle.n)})})});if(pending.length)return {decision:'guardar',reason:'Guarda al menos 1: puede servir para '+pending[0]+'.'};if(name==='Madera')return {decision:'guardar',reason:'Guárdala para el puente de la playa (300) y recetas.'};if(['Carbón','Mineral de cobre','Piedra','Fibra','Cuarzo'].includes(name))return {decision:'guardar',reason:'Conviene reservarlo para herramientas, máquinas y recetas.'};if(['Periódico mojado','CD roto','Gafas rotas','Deriva'].includes(name))return {decision:'guardar',reason:'No tiene precio de venta; guárdalo para reciclarlo.'};var item=resourceCatalog.find(function(x){return x.name.toLocaleLowerCase('es')===lower});return item&&item.price>0?{decision:'vender',reason:'Precio base estimado: '+item.price+'g por pieza. Si tienes un uso o paquete pendiente, guarda al menos una.'}:{decision:'guardar',reason:'No tiene un precio de venta conocido; guárdalo hasta identificar su uso.'}}
function resourceIsToday(row){return (+row.year||game.year)===game.year&&row.season===game.season&&+row.day===game.day}
function applyResourceDecision(row,decision,direction){direction=direction||1;if(!resourceIsToday(row))return decision;var amount=row.qty*row.price,actual=decision;if(direction>0&&actual==='vender'&&!isOpenToday('pierre',game.day,game.season,game.weather,game.year))actual='enviar';if(actual==='comprar'){if(direction>0&&amount>game.gold)return 'insuficiente';game.gold=Math.max(0,game.gold-direction*amount)}else if(actual==='vender'){game.gold=Math.max(0,game.gold+direction*amount)}else if(actual==='enviar'){if(direction>0){var due=nextDate(game.day,game.season,game.year);game.shipments=game.shipments.filter(function(x){return x.id!==row.id});game.shipments.push({id:row.id,amount:amount,due:gameDate(due.day,due.season,due.year)})}else game.shipments=game.shipments.filter(function(x){return x.id!==row.id})}return actual}
function renderResources(){
 var value=function(decision){return extra.resources.filter(function(x){return x.decision===decision}).reduce(function(a,x){return a+x.qty*x.price},0)},stocks={};
 extra.resources.forEach(function(x){if(x.decision==='guardar')stocks[x.name]=(stocks[x.name]||0)+x.qty;else if(x.decision==='vender'||x.decision==='enviar')stocks[x.name]=(stocks[x.name]||0)-x.qty});Object.keys(stocks).forEach(function(n){stocks[n]=Math.max(0,stocks[n])});
 $('#resourceSummary').innerHTML='<div class="resource-total"><small>VENTAS REGISTRADAS · ORO YA SUMADO</small><b>'+fmt(value('vender'))+'g</b></div><div class="resource-total"><small>ENVÍO · COBRO MAÑANA</small><b>'+fmt(value('enviar'))+'g</b></div><div class="resource-total"><small>COMPRAS REGISTRADAS · ORO RESTADO</small><b>'+fmt(value('comprar'))+'g</b></div><div class="resource-total"><small>MOCHILA ESTIMADA · RECOGIDO MENOS VENDIDO</small><b>'+Object.values(stocks).reduce(function(a,x){return a+x},0)+'</b></div>';
 $('#resourceOptions').innerHTML=resourceCatalog.map(function(x){return '<option value="'+x.name+'">'}).join('');
 $('#resourceList').innerHTML=extra.resources.length?extra.resources.slice().reverse().map(function(x){var advice=resourceAdvice(x.name),source=x.source||'',editable=resourceIsToday(x);return '<article class="resource-row"><span>'+(source==='Basura'?'🗑️':source==='Minas'?'⛏️':source.indexOf('suelo')>=0?'🌱':'🧺')+'</span><div><b>'+escapeHTML(x.name)+' × '+x.qty+'</b><small>'+(x.season||'Primavera')+' '+x.day+' · '+source+' · '+(advice.reason||x.note||'')+(x.decision==='guardar'?' · guardado en mochila: '+(stocks[x.name]||0):x.decision==='enviar'?' · llega mañana':x.decision==='comprar'?' · compra descontada del oro':'')+'</small></div><strong>'+fmt(x.qty*x.price)+'g</strong><select class="decision-select" data-decision="'+x.id+'" '+(editable?'':'disabled')+'><option value="guardar" '+(x.decision==='guardar'?'selected':'')+'>Guardar</option><option value="vender" '+(x.decision==='vender'?'selected':'')+'>Vender</option><option value="enviar" '+(x.decision==='enviar'?'selected':'')+'>Enviar</option><option value="comprar" '+(x.decision==='comprar'?'selected':'')+'>Comprar · descontar</option></select><button class="icon-button" data-remove-resource="'+x.id+'" aria-label="Eliminar" '+(editable?'':'disabled')+'>×</button></article>'}).join(''):'<div class="empty-state">Todavía no registraste hallazgos. La sugerencia te ayudará a reservar madera, carbón y objetos de paquetes pendientes.</div>';
}
function initExtra(){
 var seasons=['Primavera','Verano','Otoño','Invierno'];
 if(!seasons.includes(game.season))game.season='Primavera';dailySeason=season=game.season;
 $('#startDay').value=game.day;$('#gold').value=game.gold;$('#energy').value=game.maxEnergy;
 $('#communityDone').checked=!!game.communityDone;$('#desertUnlocked').checked=!!game.desertUnlocked;$('#year2').checked=game.year>=2;
 $$('#seasonToggle button,#dailySeason button').forEach(function(b){b.classList.toggle('selected',b.dataset.season===game.season)});
 $('#resourceSeason').value=game.season;$('#resourceDay').value=game.day;
 $('#startDay').addEventListener('input',function(){game.day=+$('#startDay').value||1;$('#resourceDay').value=game.day;saveExtra();updateCrop();renderDaily();renderLockedStrawberry();renderLockedDesert()});
 $('#gold').addEventListener('input',function(){game.gold=Math.max(0,+$('#gold').value||0);saveExtra();updateCrop();renderDaily()});
 $('#energy').addEventListener('input',function(){game.maxEnergy=Math.max(1,+$('#energy').value||270);saveExtra();updateCrop();renderDaily()});
 $('#dailySeason').addEventListener('click',function(e){var b=e.target.closest('[data-season]');if(!b)return;game.season=dailySeason=season=b.dataset.season;$('#resourceSeason').value=game.season;saveExtra();$$('#dailySeason button,#seasonToggle button').forEach(function(x){x.classList.toggle('selected',x.dataset.season===season)});updateCrop();renderDaily();renderLockedStrawberry();renderLockedDesert()});
 $('#seasonToggle').addEventListener('click',function(){setTimeout(function(){game.season=dailySeason=season;$('#resourceSeason').value=game.season;saveExtra();$$('#dailySeason button').forEach(function(x){x.classList.toggle('selected',x.dataset.season===season)});renderDaily()},0)});
 $('#communityDone').addEventListener('change',function(){game.communityDone=this.checked;saveExtra();updateCrop();renderDaily()});
 $('#desertUnlocked').addEventListener('change',function(){game.desertUnlocked=this.checked;saveExtra();updateCrop();renderDaily();renderLockedDesert()});
 $('#year2').addEventListener('change',function(){game.year=this.checked?Math.max(2,game.year):1;saveExtra();updateCrop();renderDaily()});
 $('#dailySummary').addEventListener('change',function(e){
  var obj=e.target.closest('[data-objective]');
  if(obj){var id=obj.dataset.objective,k=goalKey(id);if(obj.checked)extra.objectives[k]=true;else delete extra.objectives[k];if(id==='community'&&obj.checked){$('#communityDone').checked=true;game.communityDone=true}if(id==='bus'&&obj.checked){$('#desertUnlocked').checked=true;game.desertUnlocked=true}saveExtra();updateCrop();renderDaily();return}
  var route=e.target.closest('[data-route]');
  if(route){var routeId=route.dataset.route,key=gameDate()+'|route|'+routeId;extra.dailyChecks[key]=route.checked;if(routeId==='start-seeds'&&game.year===1&&game.season==='Primavera'&&game.day===1)game.hasCrops=route.checked;saveExtra();renderDaily();updateCrop();return}
  if(e.target.id==='weatherSelect')game.weather=e.target.value;
  else if(e.target.id==='hasCrops')game.hasCrops=e.target.checked;
  else if(e.target.id==='hasAnimals')game.hasAnimals=e.target.checked;
  else if(e.target.id==='hasPet')game.hasPet=e.target.checked;
  else if(e.target.id==='hasMachines')game.hasMachines=e.target.checked;
  else return;
  saveExtra();renderDaily();updateShopStatuses(game.day,game.season)
 });
 $('#dailySummary').addEventListener('click',function(e){
  if(e.target.closest('#dailyAddItem')){var itemName=$('#dailyItem').value.trim();if(!itemName){toast('Elige un objeto para registrar');return}var found=resourceCatalog.find(function(x){return x.name.toLocaleLowerCase('es')===itemName.toLocaleLowerCase('es')}),advice=resourceAdvice(itemName),decision=$('#dailyDecision').value,price=Math.max(0,+$('#dailyPrice').value||0),record={id:Date.now()+Math.random(),name:itemName,qty:Math.max(1,+$('#dailyQty').value||1),price:price,source:found?found.source:'Otro',season:game.season,year:game.year,day:game.day,note:advice.reason,decision:decision};if(decision==='comprar'&&record.qty*record.price>game.gold){toast('No alcanza el oro registrado para esa compra');return}record.decision=applyResourceDecision(record,record.decision);extra.resources.push(record);$('#gold').value=game.gold;saveExtra();renderResources();renderDaily();updateCrop();toast(record.decision==='vender'?'Venta añadida al oro del día ♡':record.decision==='enviar'?'Envío pendiente para mañana ♡':record.decision==='comprar'?'Compra descontada del oro ♡':'Hallazgo guardado ♡');return}
  if(e.target.id!=='closeDayBtn')return;
  var next=nextDate(game.day,game.season,game.year),nextKey=gameDate(next.day,next.season,next.year);game.shipments.filter(function(x){return x.due===nextKey}).forEach(function(x){game.gold+=x.amount});game.shipments=game.shipments.filter(function(x){return x.due!==nextKey});game.day=next.day;game.season=next.season;game.year=next.year;game.weather='unknown';dailySeason=season=game.season;
  $('#startDay').value=game.day;$('#gold').value=game.gold;$('#energy').value=game.maxEnergy;$('#year2').checked=game.year>=2;$('#resourceDay').value=game.day;$('#resourceSeason').value=game.season;
  $$('#dailySeason button,#seasonToggle button').forEach(function(b){b.classList.toggle('selected',b.dataset.season===season)});
  saveExtra();updateCrop();renderDaily();renderResources();renderLockedStrawberry();renderLockedDesert();
  toast('Día guardado · '+season+' '+game.day+' ♡');window.scrollTo({top:$('#diario').offsetTop-12,behavior:'smooth'})
 });
 $('#routineList').addEventListener('change',function(e){var c=e.target.closest('[data-routine]');if(!c)return;extra.routineChecks[gameDate()+'|'+c.dataset.routine]=c.checked;saveExtra()});
 $('#dayList').addEventListener('change',function(e){var c=e.target.closest('[data-day-task]');if(!c)return;var k=decodeURIComponent(c.dataset.dayTask);extra.dailyChecks[k]=c.checked;saveExtra()});
 $('#dailySummary').addEventListener('input',function(e){if(e.target.id!=='dailyItem')return;var name=e.target.value.trim(),found=resourceCatalog.find(function(x){return x.name.toLocaleLowerCase('es')===name.toLocaleLowerCase('es')});if(!found)return;var advice=resourceAdvice(name),decision=advice.decision;if(decision==='vender'&&!isOpenToday('pierre',game.day,game.season,game.weather,game.year))decision='enviar';$('#dailyPrice').value=found.price;$('#dailyDecision').value=decision;$('#dailyItemHint').textContent=advice.reason+(decision==='enviar'?' Pierre está cerrado: el envío se cobra mañana.':decision==='comprar'?' Registra compras y se descontarán del oro. Precio base: '+found.price+'g c/u.':' Precio base: '+found.price+'g por pieza.')});
 $('#resourceItem').addEventListener('input',function(){var found=resourceCatalog.find(function(x){return x.name.toLocaleLowerCase('es')===$('#resourceItem').value.trim().toLocaleLowerCase('es')});if(!found)return;var advice=resourceAdvice(found.name),decision=advice.decision;if(decision==='vender'&&!isOpenToday('pierre',game.day,game.season,game.weather,game.year))decision='enviar';$('#resourcePrice').value=found.price;$('#resourceSource').value=found.source;$('#resourceDecision').value=decision;$('#resourceSeason').value=game.season;$('#resourceDay').value=game.day;$('#resourceHint').textContent=advice.reason+(decision==='enviar'?' Pierre está cerrado: el envío se cobra mañana.':decision==='comprar'?' Registra compras y se descontarán del oro. Precio base: '+found.price+'g c/u.':' Precio base estimado: '+found.price+'g por pieza.')});
 $('#addResource').addEventListener('click',function(){var name=$('#resourceItem').value.trim();if(!name){toast('Escribe el nombre del objeto');return}var qty=Math.max(1,+$('#resourceQty').value||1),price=Math.max(0,+$('#resourcePrice').value||0),source=$('#resourceSource').value,seasonName=$('#resourceSeason').value,day=Math.min(28,Math.max(1,+$('#resourceDay').value||1)),decision=$('#resourceDecision').value,advice=resourceAdvice(name),record={id:Date.now()+Math.random(),name:name,qty:qty,price:price,source:source,season:seasonName,year:game.year,day:day,note:advice.reason,decision:decision};if(decision==='comprar'&&resourceIsToday(record)&&qty*price>game.gold){toast('No alcanza el oro registrado para esa compra');return}record.decision=applyResourceDecision(record,decision);extra.resources.push(record);$('#gold').value=game.gold;saveExtra();$('#resourceItem').value='';$('#resourceQty').value=1;$('#resourcePrice').value=0;$('#resourceDecision').value='guardar';$('#resourceHint').textContent='Precio base estimado por pieza. La sugerencia prioriza tus paquetes y materiales útiles.';renderResources();renderDaily();updateCrop();toast(record.decision==='vender'?'Venta añadida al oro del día ♡':record.decision==='enviar'?'Envío pendiente para mañana ♡':record.decision==='comprar'?'Compra descontada del oro ♡':'Hallazgo guardado ♡')});
 $('#resourceList').addEventListener('change',function(e){var sel=e.target.closest('[data-decision]');if(!sel)return;var row=extra.resources.find(function(x){return String(x.id)===sel.dataset.decision});if(row){if(sel.value==='comprar'&&resourceIsToday(row)&&row.qty*row.price>game.gold){toast('No alcanza el oro registrado para esa compra');return}if(resourceIsToday(row))applyResourceDecision(row,row.decision,-1);row.decision=applyResourceDecision(row,sel.value);$('#gold').value=game.gold;saveExtra();renderResources();renderDaily();updateCrop()}});
 $('#resourceList').addEventListener('click',function(e){var b=e.target.closest('[data-remove-resource]');if(!b)return;var row=extra.resources.find(function(x){return String(x.id)===b.dataset.removeResource});if(!row||!resourceIsToday(row))return;applyResourceDecision(row,row.decision,-1);extra.resources=extra.resources.filter(function(x){return String(x.id)!==b.dataset.removeResource});$('#gold').value=game.gold;saveExtra();renderResources();renderDaily();updateCrop()});
 $('#cropGrid').addEventListener('click',function(e){var b=e.target.closest('[data-found-crop]');if(!b)return;var name=b.dataset.foundCrop;if(!game.foundSeeds.includes(name))game.foundSeeds.push(name);saveExtra();updateCrop();renderLockedStrawberry();renderLockedDesert();toast(name+' ya está disponible ♡')});
 document.querySelectorAll('#cultivos input,#cultivos select').forEach(function(el){el.addEventListener('change',function(){renderLockedStrawberry();renderLockedDesert();renderDaily()})});
 renderDaily();renderResources();renderLockedStrawberry();renderLockedDesert();updateCrop()
}
function renderLockedDesert(){const grid=$('#cropGrid');if(!grid)return;const old=grid.querySelector('[data-desert-locked]');if(old)old.remove();if(!$('#desertUnlocked').checked){const missing=crops.filter(c=>c.season.includes(season)&&c.vendor==='Oasis (desierto)');if(missing.length){const card=document.createElement('article');card.className='crop-card strawberry-locked';card.dataset.desertLocked='1';card.innerHTML=`<div class="crop-top"><span class="crop-emoji">🚌🏜️</span><div><h3>${missing.map(c=>c.icon+' '+c.name).join(' · ')} · bloqueado</h3><small>Requiere acceso al desierto</small></div></div><p>Las semillas de ruibarbo cuestan 100g en el Oasis y no se venden en Pierre. El autobús se restaura al completar la Bóveda (42.500g) o con la ruta Joja (40.000g). El Carrito viajero puede ofrecer semillas ocasionalmente a precio variable.</p>`;grid.prepend(card)}}}
function renderLockedStrawberry(){const grid=$('#cropGrid');if(!grid)return;const exists=grid.querySelector('[data-strawberry-locked]');if(exists)exists.remove();if(season==='Primavera'&&+$('#startDay').value<13&&!$('#strawberrySeeds').checked){const card=document.createElement('article');card.className='crop-card strawberry-locked';card.dataset.strawberryLocked='1';card.innerHTML='<div class="crop-top"><span class="crop-emoji">🔒🍓</span><div><h3>Fresa · aún no disponible</h3><small>Festival del Huevo · Primavera 13</small></div></div><p>Se desbloquea para comprar en el festival, a 100g por semilla. Guarda oro hasta ese día. El Festival termina tarde; planta y riega al volver a la granja.</p><div class="quality-prices"><span>Maduración<b>8 días</b></span><span>Rebrote<b>cada 4 días</b></span><span>Precio base<b>120g</b></span><span>Primeras cosechas<b>días 21 y 25*</b></span></div><small class="locked-note">*Sin fertilizante acelerador.</small>';grid.prepend(card)}}
function renderLockedYear2(){const grid=$('#cropGrid');if(!grid)return;grid.querySelectorAll('[data-year-locked]').forEach(function(x){x.remove()});if(game.year>=2||$('#year2').checked)return;crops.filter(function(c){return c.season.includes(season)&&c.year&&c.year>game.year}).forEach(function(c){var card=document.createElement('article');card.className='crop-card strawberry-locked';card.dataset.yearLocked='1';card.innerHTML='<div class="crop-top"><span class="crop-emoji">🔒 '+c.icon+'</span><div><h3>'+c.name+' · Año '+c.year+'+</h3><small>Semilla no disponible en tu partida todavía</small></div></div><p>Este cultivo se vende en Pierre desde el año '+c.year+'. Cuando avances de año, aparecerá en el comparador de cosechas.</p>';grid.append(card)})}
function renderLockedFound(){const grid=$('#cropGrid');if(!grid)return;grid.querySelectorAll('[data-found-locked]').forEach(function(x){x.remove()});crops.filter(function(c){return c.season.includes(season)&&c.seed===0&&!game.foundSeeds.includes(c.name)}).forEach(function(c){var card=document.createElement('article');card.className='crop-card strawberry-locked';card.dataset.foundLocked='1';card.innerHTML='<div class="crop-top"><span class="crop-emoji">🌱 '+c.icon+'</span><div><h3>'+c.name+' · semilla por encontrar</h3><small>Recolección · no se compra en Pierre</small></div></div><p>El cálculo no la cuenta como gratis hasta que marques que ya encontraste una semilla.</p><button class="button-soft" data-found-crop="'+c.name+'">Ya encontré esta semilla</button>';grid.append(card)})}
function renderLockedCart(){const grid=$('#cropGrid');if(!grid)return;grid.querySelectorAll('[data-cart-locked]').forEach(function(x){x.remove()});crops.filter(function(c){return c.season.includes(season)&&c.vendor==='Carrito viajero'&&!game.foundSeeds.includes(c.name)}).forEach(function(c){var card=document.createElement('article');card.className='crop-card strawberry-locked';card.dataset.cartLocked='1';card.innerHTML='<div class="crop-top"><span class="crop-emoji">🛒 '+c.icon+'</span><div><h3>'+c.name+' · semilla rara</h3><small>Carrito viajero · viernes y domingo</small></div></div><p>La semilla cuesta 1.000g y aparece al azar en el carrito durante primavera y verano. La planta solo crece en otoño. El simulador no la cuenta hasta que marques que ya tienes una semilla.</p><button class="button-soft" data-found-crop="'+c.name+'">Ya tengo esta semilla</button>';grid.append(card)})}
initExtra();
